WITH promo_sales AS ( SELECT p.p_promo_id, i.i_product_name, CASE WHEN p.p_channel_email = 'Y' THEN 'Email' WHEN p.p_channel_tv = 'Y' THEN 'TV' WHEN p.p_channel_catalog = 'Y' THEN 'Catalog' ELSE 'Other' END AS primary_channel, cs.cs_ext_discount_amt, cs.cs_net_profit, cs.cs_order_number FROM promotion p JOIN item i ON p.p_item_sk = i.i_item_sk JOIN catalog_sales cs ON cs.cs_promo_sk = p.p_promo_sk JOIN customer c ON cs.cs_ship_customer_sk = c.c_customer_sk ) SELECT p_promo_id, i_product_name, primary_channel, SUM(cs_ext_discount_amt) AS total_discount, SUM(cs_net_profit) AS total_profit, COUNT(DISTINCT cs_order_number) AS orders, RANK() OVER (ORDER BY SUM(cs_net_profit) DESC) AS profit_rank, DENSE_RANK() OVER (ORDER BY (SUM(cs_ext_discount_amt) / NULLIF(SUM(cs_net_profit), 0)) DESC) AS discount_to_profit_rank FROM promo_sales GROUP BY p_promo_id, i_product_name, primary_channel HAVING SUM(cs_ext_discount_amt) > 0 ORDER BY profit_rank
